class Solution {
  public int largestMagicSquare(int[][] grid) {
    int m = grid.length, n = grid[0].length;
    int[][] row = new int[m][n + 1], col = new int[m + 1][n];
    for (int i = 0; i < m; i++)
      for (int j = 0; j < n; j++) {
        row[i][j + 1] = row[i][j] + grid[i][j];
        col[i + 1][j] = col[i][j] + grid[i][j];
      }
    for (int k = Math.min(m, n); k >= 1; k--) {
      for (int r = 0; r + k <= m; r++)
        for (int c = 0; c + k <= n; c++) {
          int target = row[r][c + k] - row[r][c];
          boolean ok = true;
          for (int i = r; i < r + k && ok; i++) ok = row[i][c + k] - row[i][c] == target;
          for (int j = c; j < c + k && ok; j++) ok = col[r + k][j] - col[r][j] == target;
          int a = 0, b = 0;
          for (int d = 0; d < k; d++) {
            a += grid[r + d][c + d];
            b += grid[r + d][c + k - 1 - d];
          }
          if (ok && a == target && b == target) return k;
        }
    }
    return 1;
  }
}
